    (N'Piept de pui', N'g', 165.00, 31.02, 0.00, 3.57, N'https://raw.githubusercontent.com/rstudio/EDAWR/master/data-raw/nutrition.csv', N'Chicken, broilers or fryers, breast, meat only, cooked, roasted'),
    (N'Carne tocata de vita', N'g', 254.00, 17.17, 0.00, 20.00, N'https://raw.githubusercontent.com/rstudio/EDAWR/master/data-raw/nutrition.csv', N'Beef, ground, 80% lean meat / 20% fat, raw'),
    (N'Somon', N'g', 208.00, 20.42, 0.00, 13.42, N'https://raw.githubusercontent.com/rstudio/EDAWR/master/data-raw/nutrition.csv', N'Fish, salmon, Atlantic, farmed, raw'),
    (N'Tofu', N'g', 76.00, 8.08, 1.88, 4.78, N'https://raw.githubusercontent.com/rstudio/EDAWR/master/data-raw/nutrition.csv', N'Tofu, raw, regular, prepared with calcium sulfate'),
    (N'Piper negru', N'g', 251.00, 10.39, 63.95, 3.26, N'https://raw.githubusercontent.com/rstudio/EDAWR/master/data-raw/nutrition.csv', N'Spices, pepper, black'),
    (N'Boia de ardei', N'g', 282.00, 14.14, 53.99, 12.89, N'https://raw.githubusercontent.com/rstudio/EDAWR/master/data-raw/nutrition.csv', N'Spices, paprika'),
    (N'Oregano', N'g', 265.00, 9.00, 68.92, 4.28, N'https://raw.githubusercontent.com/rstudio/EDAWR/master/data-raw/nutrition.csv', N'Spices, oregano, dried'),
    (N'Busuioc', N'g', 233.00, 22.98, 47.75, 4.07, N'https://raw.githubusercontent.com/rstudio/EDAWR/master/data-raw/nutrition.csv', N'Spices, basil, dried'),
    (N'Chimion', N'g', 375.00, 17.81, 44.24, 22.27, N'https://raw.githubusercontent.com/rstudio/EDAWR/master/data-raw/nutrition.csv', N'Spices, cumin seed');
    IF EXISTS (SELECT 1 FROM @Source s LEFT JOIN dbo.Ingredients i ON i.Name=s.Name
        LEFT JOIN dbo.Units u ON u.Abbreviation=s.UnitAbbr
        WHERE i.IngredientID IS NULL OR u.UnitID IS NULL)
        THROW 51000, N'Nutrition import requires the complete ingredient catalog and basis units.', 1;

    DECLARE @Added TABLE (IngredientID int PRIMARY KEY);
    INSERT dbo.IngredientNutrition
        (IngredientID, BasisQuantity, BasisUnitID, Calories, ProteinGrams, CarbsGrams, FatGrams, UpdatedAt)
    OUTPUT inserted.IngredientID INTO @Added
    SELECT i.IngredientID, 100, u.UnitID, s.Calories, s.Protein, s.Carbs, s.Fat, SYSUTCDATETIME()
    FROM @Source s JOIN dbo.Ingredients i ON i.Name=s.Name
    JOIN dbo.Units u ON u.Abbreviation=s.UnitAbbr
    WHERE NOT EXISTS (SELECT 1 FROM dbo.IngredientNutrition n WITH (UPDLOCK,HOLDLOCK)
        WHERE n.IngredientID=i.IngredientID);

    INSERT dbo.AuditLog (Action, EntityType, EntityID, Details, CreatedAt)
    SELECT N'INGREDIENT_NUTRITION_SET', N'Ingredient', a.IngredientID,
        LEFT(N'Catalog nutrition 2026-11-11: ' + s.SourceDescription + N'; ' + s.SourceUrl, 500), SYSUTCDATETIME()
    FROM @Added a JOIN dbo.Ingredients i ON i.IngredientID=a.IngredientID
    JOIN @Source s ON s.Name=i.Name;
    COMMIT;
    SELECT COUNT(*) AS NutritionRowsAdded FROM @Added;
END TRY
BEGIN CATCH
    IF XACT_STATE() <> 0 ROLLBACK;
    THROW;
END CATCH;
GO
